const body = $input.first().json.body ?? $input.first().json;
const tickers = (body.tickers ?? [])
  .map(t => t.toString().toUpperCase().trim())
  .filter(Boolean);

if (tickers.length === 0) throw new Error('أرسل قائمة tickers في الـ body');
if (tickers.length > 50) throw new Error('الحد الأقصى 50 سهم في طلب واحد');

return tickers.map(ticker => ({ json: { ticker } }));

const ticker = $('تقسيم الأسهم').item.json.ticker;
const data = $json;

// في حالة فشل الـ API
if (data.error || data.message) {
  return {
    json: {
      ticker,
      halal: false,
      status: 'ERROR',
      purification_rate: null,
      sector: '',
      reason: 'فشل الاتصال بـ Musaffa — مرفوض احتياطاً'
    }
  };
}

const status = data.shariaComplianceStatus ?? 'UNKNOWN';
const purification = parseFloat(data.purificationPercentage ?? 0);

// الشرط: COMPLIANT + تطهير = 0% بالضبط
const isHalal = status === 'COMPLIANT' && purification === 0;

const reason = isHalal ? '' :
  status !== 'COMPLIANT'
    ? `الحالة: ${status}`
    : `نسبة تطهير ${purification}% — يجب أن تكون 0%`;

return {
  json: {
    ticker,
    halal: isHalal,
    purification_rate: purification,
    status,
    sector: data.businessSector ?? '',
    reason
  }
};

const all = $input.all().map(i => i.json);

const halal = all.filter(r => r.halal).map(r => r.ticker);
const rejected = {};
all.filter(r => !r.halal).forEach(r => {
  rejected[r.ticker] = r.reason;
});

return [{
  json: {
    halal,
    rejected,
    total: all.length,
    halal_count: halal.length,
    details: all
  }
}];
